# frozen_string_literal: true
# The discovery page reads accepted file manifests; it never regenerates downloads.
def print_library_items
 @print_library_items ||= [ ['gada-a3','year'], ['menesa-a3','month'] ].flat_map do |directory,period|
  JSON.parse(File.read("downloads/#{directory}/manifest.json")).fetch('items').map do |item|
   preview=PreviewComponents::PREVIEWS.fetch(item.fetch('preview'))
   small=preview.fetch('variants').min_by{|variant|(variant.fetch('width')-480).abs}
   {id:File.basename(item.fetch('pdf'),'.pdf')+"-#{period}",year:item.fetch('year'),month:item['month'],period:period,
    title:item.fetch('title'),orientation:item.fetch('orientation'),holidays:item.fetch('holidays'),
    pdf:item.fetch('pdf'),image:item.fetch('image'),preview:small.fetch('src'),width:small.fetch('width'),height:small.fetch('height')}
  end
 end
end

def print_library_icon(type)
 type=='arrow' ? '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg>' : '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/></svg>'
end

def print_library_card(item)
 period=item[:month] ? "#{item[:year]}. gada #{GEN[item[:month]-1]} kalendārs" : "#{item[:year]}. gada kalendārs"
 orientation=item[:orientation]=='portrait' ? 'Vertikāli' : 'Horizontāli'
 holiday=item[:holidays] ? 'Ar svētku dienām' : 'Bez svētku atzīmēm'
 %(<article class="print-library-card"><a class="print-library-preview" href="#{h(item[:image])}" target="_blank" rel="noopener"><img src="#{h(item[:preview])}" width="#{item[:width]}" height="#{item[:height]}" alt="#{h(item[:title])}: #{h(period)}" loading="lazy" decoding="async"><span>Apskatīt #{print_library_icon('arrow')}</span></a><div class="print-library-card-copy"><small>#{h(period)}</small><h3>#{h(item[:title])}</h3><p>A3 · #{orientation} · #{holiday}</p><div class="print-library-downloads">#{[['pdf','PDF','file-pdf'],['image','Attēls','file-image']].map{|key,label,icon|%(<a href="#{h(item[key.to_sym])}" download aria-label="Lejupielādēt #{h(item[:title])}: #{label}"><img src="/assets/#{icon}.svg" width="24" height="24" alt=""><span>#{label}</span>#{print_library_icon('download')}</a>)}.join}</div></div></article>)
end

def print_library_markup
 items=print_library_items
 File.write('assets/print-library-data.json',JSON.generate({version:1,items:items})+"\n")
 years=(2027..2030).map do |year|
  days=(Date.new(year,12,31)-Date.new(year,1,1)).to_i+1
  %(<a class="print-year-card print-year-card--#{year}" href="/pdf-kalendari/#{year}/"><figure><img src="/assets/print-collections/#{year}.svg?v={{ site.data.build.asset_version }}" alt="" width="360" height="280" loading="lazy" decoding="async"></figure><div><h3>#{year}<span>#{print_library_icon('arrow')}</span></h3><p>#{days} dienas · 15 gada dizaini</p><strong>Atvērt kolekciju</strong></div></a>)
 end.join
 initial=items.select{|item|item[:year]==2027&&item[:period]=='year'}.first(6).map{|item|print_library_card(item)}.join
 %(<section class="print-library-hero"><div class="print-library-hero-copy"><span class="eyebrow">LATVIJAS KALENDĀRI · 2027–2030</span><h1>PDF kalendāri.<br><span>Tavam gadam un mēnesim.</span></h1><p>Kalendārs, kuru gribas turēt acu priekšā. Izvēlies savu gadu, atrodi piemērotu dizainu un saglabā PDF drukāšanai vai attēlu ikdienas plāniem.</p><a class="print-library-primary" href="#drukas-izvele">Atrast savu kalendāru #{print_library_icon('arrow')}</a><div class="print-library-facts"><span><strong>4</strong>gadi</span><span><strong>48</strong>mēneši</span><span><strong>15</strong>dizaini katram periodam</span></div></div><figure class="print-library-hero-art"><img src="/assets/print-collections/studio.svg?v={{ site.data.build.asset_version }}" width="620" height="430" alt="Kalendārs365 galda, sienas un spirāles kalendāru vektoru kompozīcija" fetchpriority="high" decoding="async"><figcaption>Tavs laiks. Tavs noformējums.</figcaption></figure></section>
 <section class="print-library-years" aria-labelledby="print-years-title"><div class="print-library-section-heading"><div><span class="eyebrow">SĀC AR SAVU GADU</span><h2 id="print-years-title">Katram gadam sava kolekcija</h2></div><p>Gada pārskats un visi 12 mēneši vienuviet.</p></div><div class="print-library-year-grid">#{years}</div></section>
 <section class="print-library-browser" id="drukas-izvele" data-print-library aria-labelledby="print-library-title"><div class="print-library-section-heading"><div><span class="eyebrow">IZVĒLIES UN LEJUPIELĀDĒ</span><h2 id="print-library-title">Atrodi savu kalendāru</h2></div><span class="print-library-quality">A3 · 600 dpi</span></div><p class="print-library-intro">Viss gads vienā lapā vai vairāk vietas vienam mēnesim? Atlasi gadu, lapas virzienu un svētku atzīmes. Dizainu vari apskatīt pirms lejupielādes.</p><div class="print-library-filters"><label>Gads<select name="gads" data-print-filter="year">#{(2027..2030).map{|year|%(<option value="#{year}">#{year}</option>)}.join}</select></label><label>Periods<select name="periods" data-print-filter="period"><option value="year">Viss gads</option><option value="month">Viens mēnesis</option></select></label><label data-print-month-label hidden>Mēnesis<select name="menesis" data-print-filter="month">#{MONTHS.each_with_index.map{|name,index|%(<option value="#{index+1}">#{name.capitalize}</option>)}.join}</select></label><label>Lapas virziens<select name="virziens" data-print-filter="orientation"><option value="all">Abi virzieni</option><option value="portrait">Vertikāli</option><option value="landscape">Horizontāli</option></select></label><label>Svētku atzīmes<select name="svetki" data-print-filter="holidays"><option value="all">Visi dizaini</option><option value="yes">Ar svētku dienām</option><option value="no">Bez svētku atzīmēm</option></select></label><label class="print-library-search">Dizaina nosaukums<input type="search" data-print-filter="query" placeholder="Piemēram, Rīga vai mežs" maxlength="80"></label></div><div class="print-library-result-bar"><p data-print-library-status role="status" aria-live="polite">2027. gada kalendāri · 15 dizaini</p><button type="button" class="print-library-reset" data-print-library-reset hidden>Notīrīt filtrus</button><a data-print-period-link href="/pdf-kalendari/2027/">Atvērt perioda kolekciju #{print_library_icon('arrow')}</a></div><div class="print-library-results" data-print-library-results>#{initial}</div><div class="print-library-empty" data-print-library-empty hidden><h3>Šādai atlasei dizainu nav.</h3><p>Pamēģini citu nosaukumu vai noņem lapas virziena un svētku filtrus.</p><button type="button" data-print-library-clear>Parādīt visus perioda dizainus</button></div><div class="print-library-load"><button type="button" data-print-library-more>Parādīt vēl 6 dizainus #{print_library_icon('arrow')}</button></div><noscript><p>Visi dizaini pieejami arī gada kolekcijās. Izvēlies gadu augstāk, lai atvērtu tā mēnešus un pilno lejupielāžu sarakstu.</p></noscript></section>
 <section class="print-library-guide" aria-labelledby="print-guide-title"><div><span class="eyebrow">PIRMS DRUKĀŠANAS</span><h2 id="print-guide-title">No ekrāna uz tavu galdu</h2><p>Gada kalendārs palīdz vienā skatienā salīdzināt mēnešus un ieplānot atpūtu. Mēneša kalendārā ērtāk pārskatīt tuvākās nedēļas. Ja vajadzīgs savs teksts, fotoattēls vai krāsas, izmanto <a href="/izveidot-kalendaru/">kalendāra veidotāju</a>.</p><p>Latvijas svētku brīvdienas atzīmētas tajos dizainos, kuriem norādīts «Ar svētku dienām». Pārējās veidnes piedāvā mierīgāku datumu pārskatu bez šīm atzīmēm. Darba plāniem salīdzini <a href="/darba-dienu-kalendars/">darba dienas un stundas</a>, bet īpašos datumus pārbaudi <a href="/svetku-dienas/">svētku dienu kalendārā</a>.</p></div><div class="print-library-tips"><article><img src="/assets/file-pdf.svg" width="40" height="40" alt=""><div><h3>PDF drukāšanai</h3><p>Atver failu un izvēlies A3 lapu atbilstošajā virzienā. Drukājot uz A4, priekšskatījumā pārbaudi iestatījumu «Ietilpināt lapā».</p></div></article><article><img src="/assets/file-image.svg" width="40" height="40" alt=""><div><h3>Attēls saglabāšanai</h3><p>Pilnas izšķirtspējas attēlu vari glabāt ierīcē vai nosūtīt citiem. Izdrukai izmanto lejupielādēto failu, nevis ekrānuzņēmumu.</p></div></article><details><summary>Vai varu pievienot savus notikumus?</summary><p>Šīs gatavās veidnes lejupielādē to esošajā noformējumā. Saviem notikumiem izmanto <a href="/menesa-kalendars/">interaktīvo mēneša kalendāru</a> vai <a href="/izveidot-kalendaru/">kalendāra veidotāju</a>.</p></details></div></section>)
end
